async(page)=>{
 const checks=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-experience/';const assert=(ok,m)=>{if(!ok)throw Error(m)};
 const role=async r=>{await page.locator(`[data-role=${r}]`).first().click();if(r==='dispatch')await page.locator('[data-dispatch-tab=orders]').click()};const open=async a=>page.locator(`[data-action=${a}]`).first().click();
 const fill=async p=>{for(const [k,v]of Object.entries(p)){const el=page.locator(`#action-form [name=${k}]`);if(k==='vehicle'){await page.locator(`[name=vehicle][value=${v}]`).check();continue;}if(typeof v==='boolean')await el.setChecked(v);else if(await el.evaluate(x=>x.tagName)==='SELECT')await el.selectOption(String(v));else await el.fill(String(v))}};
 const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden',timeout:4000})};const act=async(a,p={})=>{await open(a);await fill(p);await submit()};const state=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('routefit-r1-prototype-v1')));const close=async()=>{await page.locator('[data-close]').first().click();if(await page.locator('#dialog').isVisible())await page.locator('[data-close]').first().click()};
 const copied='来源平台：DEMO-Shop\n外部订单号：DEMO-PASTE-001\n上门收货地址：演示取件地点 A 东门\n联系人：演示寄件人\n电话：+855000000001\n送货地址：演示收货地点 B 南门\n收货人：演示收件人\n联系电话：+855000000002\n配送价格：USD 20\n配送保险价格：USD 2\n商品金额：999';
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1000});await role('dispatch');await open('qa');await act('reset');await role('ops');await page.locator('[data-nav=integrations]').click();await open('importExternal');await page.locator('#external-paste').fill(copied);await page.locator('[data-parse-external]').click();assert((await page.locator('#parse-feedback').innerText()).includes('商品金额'),'ambiguous amount not flagged');assert(await page.locator('[name=pickupPhone]').inputValue()==='+855000000001','pickup phone swapped');assert(await page.locator('[name=deliveryPhone]').inputValue()==='+855000000002','delivery phone swapped');await fill({sourceType:'customer',cargo:'演示包装箱',qty:2,weight:10,length:40,width:30,height:20,expected:'2026-10-24T18:00'});await page.locator('#action-form [type=submit]').click();await page.waitForFunction(()=>document.querySelector('#form-error').textContent.includes('核对'));await fill({reviewed:true});await submit();let db=await state();const id=db.orders[0].id;assert(db.orders[0].amountMinor===2200,'insurance total missing');assert(db.orders[0].status==='draft'&&!db.orders[0].vehicle,'import prematurely assigned');checks.push('复制取送地址/两组联系人电话/配送和保险价格，未知商品金额提示、人工校对后只建草稿');
 await page.locator(`[data-intake-request="${id}"]`).click();await submit();assert((await state()).orders[0].status==='draft','request bypassed verification');await page.screenshot({path:base+'intake-requested.png',fullPage:true});await page.locator(`[data-intake-open="${id}"]`).click();await open('promise');await fill({basis:'DEMO 取送地址与车辆已核验',commissionPercent:20,address:true,measured:true,confirmed:true});await page.locator('#action-form [type=submit]').click();await page.waitForFunction(()=>document.querySelector('#form-error').textContent.includes('承保'));await fill({insuranceProvider:'DEMO 保险提供方',insurancePolicy:'DEMO-POLICY-001',insuranceConfirmed:true});await page.screenshot({path:base+'insurance-confirmation.png',fullPage:true});await submit();await act('offer',{vehicle:'V01'});checks.push('派单申请与实际派车分离；保险报价不能代替人工承保凭证核对');
 await role('driver');assert((await page.locator('main').innerText()).includes('演示取件地点 A 东门'),'driver pickup missing');assert((await page.locator('main').innerText()).includes('+855000000002'),'driver delivery contact missing');await act('accept');await role('warehouse');await act('prepare',{dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await role('driver');await act('pickup',{evidence:'DEMO-HANDOVER'});await act('depart');await act('report',{proof:'DEMO-CASH'});await act('deliver',{receiver:'演示收件人',evidence:'DEMO-POD'});await role('finance');await act('verify',{evidence:'DEMO-COUNT'});await role('driver');await act('remit',{evidence:'DEMO-REMIT'});await role('finance');await act('reconcile',{evidence:'DEMO-RECON'});await page.locator('[data-nav=pricing]').click();await page.locator('[data-section-tab=orders]').click();await page.locator(`[data-resource="${id}"]`).click();await act('earningPost',{evidence:'DEMO-SPLIT'});db=await state();assert(db.earnings[0].insuranceMinor===200&&db.earnings[0].platformMinor===400&&db.earnings[0].driverMinor===1600,'insurance entered commission');await page.locator('[data-section-tab=earnings]').click();await page.screenshot({path:base+'insurance-ledger.png',fullPage:true});checks.push('司机查看完整取送联系信息，22美元收款与核验，保险2美元另记，配送20美元按比例分成');
 await role('ops');await page.locator('[data-nav=integrations]').click();await open('importExternal');await page.locator('#external-paste').fill(copied);await page.locator('[data-parse-external]').click();await fill({sourceType:'customer',cargo:'演示包装箱',qty:2,weight:10,length:40,width:30,height:20,expected:'2026-10-24T18:00',reviewed:true});await submit();assert((await state()).externalIntakes.length===1,'duplicate import created another order');await open('importExternal');await page.locator('#external-paste').fill(copied);await page.locator('[data-parse-external]').click();await fill({sourceType:'customer',cargo:'演示包装箱',qty:2,weight:10,length:40,width:30,height:20,expected:'2026-10-24T18:00',amount:99,reviewed:true});await page.locator('#action-form [type=submit]').click();await page.waitForFunction(()=>document.querySelector('#form-error').textContent.includes('已存在'));await close();checks.push('重复来源订单不重复创建，内容不同禁止覆盖');
 await open('importExternal');await page.locator('#external-paste').fill(copied.replace('DEMO-PASTE-001','DEMO-WMS-001'));await page.locator('[data-parse-external]').click();await fill({sourceType:'warehouse',cargo:'演示包装箱',qty:2,weight:10,length:40,width:30,height:20,expected:'2026-10-24T18:00',insuranceAmount:0,reviewed:true});await submit();await page.locator('[data-section-tab=warehouse]').click();assert((await page.locator('tbody').innerText()).includes('DEMO-WMS-001'),'warehouse filter missing');await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'intake mobile overflow');await page.reload();assert((await state()).externalIntakes.length===2,'reload lost imports');checks.push('仓库与用户平台分组、390px布局、刷新保留');await page.setViewportSize({width:1440,height:1000});await role('customer');assert(!await page.locator('tbody [data-intake-open]').count(),'customer can dispatch');await page.locator('[data-section-tab=myOrders]').click();assert((await page.locator('.customer-body').innerText()).includes('暂无配送记录'),'other sources leaked to user');await page.locator('[data-section-tab=list]').click();await open('importExternal');await page.locator('#external-paste').fill(copied.replace('DEMO-PASTE-001','DEMO-USER-ORDER-001'));await page.locator('[data-parse-external]').click();assert(await page.locator('[name=sourcePlatform]').inputValue()==='DEMO-Shop','source platform not preserved');await fill({cargo:'演示用户包裹',qty:1,weight:10,length:40,width:30,height:20,expected:'2026-10-24T18:00',insuranceAmount:0,reviewed:true});await submit();db=await state();const userOrder=db.orders[0];assert(userOrder.externalSource.sourceSystem==='DEMO-USER-001','user source spoofed');await page.locator('[data-section-tab=myOrders]').click();await page.locator(`[data-intake-request="${userOrder.id}"]`).click();await submit();assert((await state()).orders[0].status==='draft','user bypassed dispatch');await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'user mobile overflow');await page.screenshot({path:base+'customer-intake.png',fullPage:true});checks.push('独立用户入口只展示本人申请，保留来源平台，可复制下单和申请派单但无调度操作');return {status:'PASS',checks};
}
